#include <bits/stdc++.h>
using namespace std;

int n, a[105];
int dp[105][105][105][3];

int solve(int idx, int evenLeft, int oddLeft, int last) {
    if (evenLeft < 0 || oddLeft < 0) return 1e9;
    if (idx == n) return (evenLeft == 0 && oddLeft == 0) ? 0 : (int)1e9;

    int &res = dp[idx][evenLeft][oddLeft][last];
    if (res != -1) return res;

    res = 1e9;

    if (a[idx] != 0) {
        int parity = a[idx] & 1;
        res = solve(idx + 1, evenLeft, oddLeft, parity)
            + (last != 2 && last != parity);
    } else {
        if (evenLeft > 0) {
            res = min(res, solve(idx + 1, evenLeft - 1, oddLeft, 0)
                           + (last != 2 && last != 0));
        }
        if (oddLeft > 0) {
            res = min(res, solve(idx + 1, evenLeft, oddLeft - 1, 1)
                           + (last != 2 && last != 1));
        }
    }

    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;

    int usedEven = 0, usedOdd = 0;
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        if (a[i] != 0) {
            if (a[i] & 1) ++usedOdd;
            else ++usedEven;
        }
    }

    int evenLeft = n / 2 - usedEven;
    int oddLeft = (n + 1) / 2 - usedOdd;

    memset(dp, -1, sizeof(dp));
    cout << solve(0, evenLeft, oddLeft, 2) << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> a(n);
    int fixedEven = 0, fixedOdd = 0;

    for (int &x : a) {
        cin >> x;
        if (x != 0) {
            if (x % 2 == 0) ++fixedEven;
            else ++fixedOdd;
        }
    }

    int remainingEven = n / 2 - fixedEven;
    int remainingOdd = (n + 1) / 2 - fixedOdd;
    const int INF = 1e9;

    vector<vector<array<int, 2>>> dp(
        n + 1, vector<array<int, 2>>(remainingEven + 1, {INF, INF})
    );

    if (a[0] == 0) {
        if (remainingEven > 0) dp[1][1][0] = 0;
        if (remainingOdd > 0) dp[1][0][1] = 0;
    } else {
        dp[1][0][a[0] & 1] = 0;
    }

    int zerosProcessed = (a[0] == 0);

    for (int i = 1; i < n; ++i) {
        int nextZerosProcessed = zerosProcessed + (a[i] == 0);

        for (int usedEven = 0; usedEven <= remainingEven; ++usedEven) {
            int usedOdd = zerosProcessed - usedEven;
            if (usedOdd < 0 || usedOdd > remainingOdd) continue;

            for (int previousParity = 0; previousParity < 2; ++previousParity) {
                int currentCost = dp[i][usedEven][previousParity];
                if (currentCost == INF) continue;

                if (a[i] != 0) {
                    int parity = a[i] & 1;
                    dp[i + 1][usedEven][parity] =
                        min(dp[i + 1][usedEven][parity],
                            currentCost + (previousParity != parity));
                } else {
                    if (usedEven < remainingEven) {
                        dp[i + 1][usedEven + 1][0] =
                            min(dp[i + 1][usedEven + 1][0],
                                currentCost + (previousParity != 0));
                    }
                    if (usedOdd < remainingOdd) {
                        dp[i + 1][usedEven][1] =
                            min(dp[i + 1][usedEven][1],
                                currentCost + (previousParity != 1));
                    }
                }
            }
        }

        zerosProcessed = nextZerosProcessed;
    }

    cout << min(dp[n][remainingEven][0], dp[n][remainingEven][1]) << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> a(n);
    int even = n / 2;
    int odd = (n + 1) / 2;

    for (int &x : a) {
        cin >> x;
        if (x != 0) {
            if (x % 2 == 0) --even;
            else --odd;
        }
    }

    const int INF = 1e9;
    static int dp[105][105][3];
    static int nextDp[105][105][3];

    fill(&dp[0][0][0], &dp[0][0][0] + 105 * 105 * 3, INF);
    dp[even][odd][2] = 0;

    for (int x : a) {
        fill(&nextDp[0][0][0], &nextDp[0][0][0] + 105 * 105 * 3, INF);

        for (int e = 0; e <= even; ++e) {
            for (int o = 0; o <= odd; ++o) {
                for (int last = 0; last < 3; ++last) {
                    if (dp[e][o][last] == INF) continue;

                    if (x != 0) {
                        int parity = x % 2;
                        int cost = (last != 2 && last != parity);
                        nextDp[e][o][parity] =
                            min(nextDp[e][o][parity], dp[e][o][last] + cost);
                    } else {
                        if (e > 0) {
                            int cost = (last != 2 && last != 0);
                            nextDp[e - 1][o][0] =
                                min(nextDp[e - 1][o][0], dp[e][o][last] + cost);
                        }
                        if (o > 0) {
                            int cost = (last != 2 && last != 1);
                            nextDp[e][o - 1][1] =
                                min(nextDp[e][o - 1][1], dp[e][o][last] + cost);
                        }
                    }
                }
            }
        }

        memcpy(dp, nextDp, sizeof(dp));
    }

    cout << min(dp[0][0][0], dp[0][0][1]) << '\n';
    return 0;
}

